function dget(string $path,mixed $def=null):mixed{$path=trim($path,'/');if(furls()){$r=frequest('GET',$path);if($r['ok'])return$r['data']??$def;} $d=local_db();if($path==='')return$d;$c=$d;foreach(explode('/',$path) as $p){if($p==='')continue;if(!is_array($c)||!array_key_exists($p,$c))return$def;$c=$c[$p];}return$c;}
function dset(string $path,mixed $v):bool{$path=trim($path,'/');if(furls()){$r=frequest('PUT',$path,$v);if($r['ok'])return true;} $d=local_db();$p=array_values(array_filter(explode('/',$path),fn($x)=>$x!==''));if(!$p)return save_db(is_array($v)?$v:$d);$r=&$d;foreach($p as $i=>$x){if($i===count($p)-1){$r[$x]=$v;break;}if(!isset($r[$x])||!is_array($r[$x]))$r[$x]=[];$r=&$r[$x];}return save_db($d);}
function dpatch(string $path,array $v):bool{$old=dget($path,[]);if(!is_array($old))$old=[];return dset($path,array_replace_recursive($old,$v));}
