function tg(string $method,array $p=[]):array{if(BOT_TOKEN==='')return['ok'=>false,'error'=>'bot_not_configured'];$u='https://api.telegram.org/bot'.rawurlencode(BOT_TOKEN).'/'.$method;$ch=curl_init($u);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$p,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>15]);$b=curl_exec($ch);$e=curl_error($ch);curl_close($ch);if($b===false)return['ok'=>false,'error'=>$e];$x=json_decode((string)$b,true);return is_array($x)?$x:['ok'=>false,'error'=>'invalid'];}
function verify_init(string $raw):array{if($raw===''||BOT_TOKEN==='')return['ok'=>false,'error'=>'missing_init_data'];parse_str($raw,$d);$hash=(string)($d['hash']??'');if($hash==='')return['ok'=>false,'error'=>'missing_hash'];unset($d['hash']);ksort($d);$parts=[];foreach($d as $k=>$v)$parts[]=$k.'='.$v;$secret=hash_hmac('sha256',BOT_TOKEN,'WebAppData',true);$calc=hash_hmac('sha256',implode("\n",$parts),$secret);if(!hash_equals($calc,$hash))return['ok'=>false,'error'=>'invalid_hash'];$auth=(int)($d['auth_date']??0);if($auth<=0||n()-$auth>86400)return['ok'=>false,'error'=>'expired_init_data'];$u=dec((string)($d['user']??'{}'),[]);return is_array($u)&&!empty($u['id'])?['ok'=>true,'user'=>$u]:['ok'=>false,'error'=>'missing_user'];}
function level(int $xp):array{$lv=dget('settings/levels',[]);$best=['level'=>1,'xp'=>0,'badge'=>'Rookie'];foreach((array)$lv as $x){if($xp>=(int)($x['xp']??0))$best=['level'=>(int)($x['level']??1),'xp'=>(int)($x['xp']??0),'badge'=>(string)($x['badge']??'Rookie')];}return$best;}
function progress(int $xp):array{$lv=dget('settings/levels',[]);usort($lv,fn($a,$b)=>(int)($a['xp']??0)<=>(int)($b['xp']??0));$cur=level($xp);$next=$cur['xp']+100;foreach($lv as $x){if((int)($x['xp']??0)>$xp){$next=(int)$x['xp'];break;}}$span=max(1,$next-$cur['xp']);return['current'=>$cur,'next_xp'=>$next,'progress'=>round(max(0,min(100,($xp-$cur['xp'])/$span*100)),2)];}
