function choose_manager(string $preferred=''):string{if($preferred!==''&&getr('managers',$preferred)&&!empty(getr('managers',$preferred)['active']))return$preferred;$best='';$count=PHP_INT_MAX;$global=(int)dget('settings/manager_max_open',MANAGER_MAX_OPEN);foreach(managers() as $id=>$m){if(empty($m['active']))continue;$limit=(int)($m['max_open']??$global);$c=manager_count((string)$id);if($c>=$limit)continue;if($c<$count){$count=$c;$best=(string)$id;}}return$best;}
function upload_proof(string $field,string $id):array{if(empty($_FILES[$field]))return['ok'=>false,'error'=>'file_required'];$f=$_FILES[$field];if(($f['error']??1)!==UPLOAD_ERR_OK)return['ok'=>false,'error'=>'upload_error'];if((int)$f['size']<=0||(int)$f['size']>MAX_UPLOAD_BYTES)return['ok'=>false,'error'=>'file_size'];$fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($f['tmp_name'])?:'';$map=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($map[$mime]))return['ok'=>false,'error'=>'mime'];if(!is_dir(UPLOAD_DIR))@mkdir(UPLOAD_DIR,0755,true);$name=hash('sha256',$id.'|'.microtime(true).'|'.bin2hex(random_bytes(10))).'.'.$map[$mime];$path=UPLOAD_DIR.'/'.$name;if(!move_uploaded_file($f['tmp_name'],$path))return['ok'=>false,'error'=>'save'];return['ok'=>true,'name'=>$name,'path'=>$path,'sha'=>hash_file('sha256',$path),'mime'=>$mime,'size'=>(int)$f['size']];}
