function action():string{return text((string)($_GET['action']??''),80);}

function safe_profile_url(string $v): string { $v=trim($v);$p=parse_url($v);if(!$p||empty($p['scheme'])||!in_array(strtolower($p['scheme']),['http','https'],true)||empty($p['host']))return '';return $v; }
function profile_fetch(string $url): array { $url=safe_profile_url($url);if($url==='')return['ok'=>false,'error'=>'invalid_profile_url'];$ch=curl_init($url);if($ch===false)return['ok'=>false,'error'=>'curl_init'];curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_CONNECTTIMEOUT=>7,CURLOPT_TIMEOUT=>15,CURLOPT_USERAGENT=>'Mozilla/5.0 FoxiGrowVerifier']);$raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($raw===false||$code<200||$code>=400)return['ok'=>false,'error'=>'profile_fetch_failed'];return['ok'=>true,'text'=>html_entity_decode(strip_tags((string)$raw),ENT_QUOTES|ENT_HTML5,'UTF-8')];}
function profile_provider(string $url): string { $h=strtolower((string)(parse_url($url,PHP_URL_HOST)??''));if(str_contains($h,'youtube.com')||str_contains($h,'youtu.be'))return'youtube';if(str_contains($h,'facebook.com'))return'facebook';if(str_contains($h,'instagram.com'))return'instagram';if(str_contains($h,'twitter.com')||str_contains($h,'x.com'))return'twitter';if(str_contains($h,'tiktok.com'))return'tiktok';return'website'; }
function binding_verify(string $userId,array $task,string $profile): array { $profile=safe_profile_url($profile);if($profile==='')return['ok'=>false,'error'=>'invalid_profile_url'];$provider=strtolower((string)($task['binding_provider']??$task['category']??''));if($provider!==''&&$provider!=='binding'&&profile_provider($profile)!==$provider)return['ok'=>false,'error'=>'wrong_platform'];$marker=trim((string)($task['verification_marker']??''));if($marker==='')return['ok'=>false,'error'=>'verification_marker_missing'];$fetch=profile_fetch($profile);if(!$fetch['ok'])return$fetch;if(stripos($fetch['text'],$marker)===false)return['ok'=>false,'error'=>'verification_code_not_found'];$row=['user_id'=>$userId,'provider'=>$provider,'profile_url'=>$profile,'marker'=>$marker,'verified_at'=>iso(),'task_id'=>(string)($task['id']??'')];dset('bindings/'.$userId.'/'.$provider,$row);return['ok'=>true,'binding'=>$row];}
function binding_claim(string $taskId,string $userId,float $reward,int $xp): array { if(dget('binding_claims/'.$taskId.'/'.$userId,null)!==null)return['ok'=>false,'error'=>'binding_already_claimed'];$u=getr('users',$userId);if(!$u)return['ok'=>false,'error'=>'not_found'];$u['balance']=money(($u['balance']??0)+$reward);$u['xp']=(int)($u['xp']??0)+$xp;$u['tasks_completed']=(int)($u['tasks_completed']??0)+1;setr('users',$userId,$u);dset('binding_claims/'.$taskId.'/'.$userId,['task_id'=>$taskId,'user_id'=>$userId,'created_at'=>iso()]);dset('transactions/'.uuid(),['user_id'=>$userId,'type'=>'binding_reward','amount'=>$reward,'task_id'=>$taskId,'created_at'=>iso()]);notify($userId,'Account verified','+' .money($reward).' USDT added','success');return['ok'=>true,'user'=>$u,'reward'=>$reward];}
function bind_platform_allowed(string $provider): bool { return in_array(strtolower($provider),['youtube','facebook','twitter','instagram','tiktok'],true); }

function api(){
    $a=action();
    if($a==='init'){ $d=input();$v=verify_init((string)($d['initData']??''));if(!$v['ok'])out($v,401);$u=ensure_user($v['user'],text((string)($d['start_param']??''),200));$_SESSION['tg_user_id']=(string)$u['telegram_id'];$j=join_check((string)$u['telegram_id']);fraud((string)$u['telegram_id']);out(['ok'=>true,'user'=>$u,'join'=>$j,'config'=>['app_name'=>APP_NAME,'version'=>APP_VERSION,'telegram_username'=>TELEGRAM_USERNAME,'monetag_zone'=>MONETAG_ZONE_ID,'monetag_rewarded_url'=>MONETAG_REWARDED_URL,'csrf'=>csrf()]]);}
    if($a==='bootstrap'){ $u=require_user();$tasks=[];foreach(cget('tasks') as $id=>$t){if(is_array($t)&&task_live($t)){$t['id']=$id;$t['user_completed']=!empty(getr('claims',claimkey($id,$u['telegram_id']))['completed']);$tasks[]=$t;}}usort($tasks,fn($x,$y)=>(int)($y['priority']??0)<=>(int)($x['priority']??0));$leaders=[];foreach(cget('users') as $id=>$x){if(is_array($x))$leaders[]=['telegram_id'=>$id,'name'=>$x['name']??'User','username'=>$x['username']??'','photo_url'=>$x['photo_url']??'','balance'=>money($x['balance']??0),'tasks_completed'=>(int)($x['tasks_completed']??0),'level'=>level((int)($x['xp']??0))];}usort($leaders,fn($x,$y)=>($y['tasks_completed']<=>$x['tasks_completed'])?:($y['balance']<=>$x['balance']));$w=[];foreach(cget('withdrawals') as $x)if(($x['telegram_id']??'')===$u['telegram_id'])$w[]=$x;usort($w,fn($x,$y)=>(int)($y['ts']??0)<=>(int)($x['ts']??0));out(['ok'=>true,'user'=>$u,'level'=>progress((int)($u['xp']??0)),'tasks'=>$tasks,'leaders'=>array_slice($leaders,0,30),'withdrawals'=>array_slice($w,0,50),'spin'=>spin_state($u['telegram_id']),'streak'=>streak_state($u['telegram_id']),'ads'=>ad_status($u['telegram_id']),'join'=>join_check($u['telegram_id']),'notifications'=>count(array_filter(cget('notifications/'.$u['telegram_id']),fn($x)=>empty($x['read']))),'settings'=>dget('settings',[]) ]);}
    if($a==='join'){ $u=require_user();out(join_check($u['telegram_id']));}
    if($a==='tasks'){ $u=require_user();$cat=text((string)($_GET['category']??''),40);$arr=[];foreach(cget('tasks') as $id=>$t){if(is_array($t)&&task_live($t)&&($cat===''||($t['category']??'')===$cat)){$t['id']=$id;$t['user_completed']=!empty(getr('claims',claimkey($id,$u['telegram_id']))['completed']);$arr[]=$t;}}out(['ok'=>true,'tasks'=>$arr]);}
    if($a==='task_open'){ $u=require_user();$d=input();$id=text((string)($d['task_id']??''),100);$t=getr('tasks',$id);if(!$t||!task_live($t))out(['ok'=>false,'error'=>'task_unavailable'],404);$ck=claimkey($id,$u['telegram_id']);$c=getr('claims',$ck);if(!$c){$c=['task_id'=>$id,'telegram_id'=>$u['telegram_id'],'opened_at'=>iso(),'ts'=>n(),'completed'=>false];setr('claims',$ck,$c);}out(['ok'=>true,'task'=>$t,'claim'=>$c]);}
    if($a==='task_submit'){ $u=require_user();$id=text((string)($_POST['task_id']??''),100);$t=getr('tasks',$id);if(!$t||!task_live($t))out(['ok'=>false,'error'=>'task_unavailable'],404);$ck=claimkey($id,$u['telegram_id']);if(!getr('claims',$ck))out(['ok'=>false,'error'=>'task_not_opened'],400);$profile=url((string)($_POST['profile_link']??''));if(!empty($t['require_profile_link'])&&$profile==='')out(['ok'=>false,'error'=>'profile_link_required'],400);$upload=['ok'=>true,'name'=>'','sha'=>''];if(!empty($t['require_screenshot'])){$upload=upload_proof('proof',$u['telegram_id']);if(!$upload['ok'])out($upload,400);if(duplicate_proof($upload['sha'])){@unlink($upload['path']);out(['ok'=>false,'error'=>'duplicate_proof'],409);} }if(!empty($t['require_review'])||!empty($t['require_screenshot'])||!empty($t['require_profile_link'])){$sid0=uuid();$mid=choose_manager((string)($t['manager_id']??''));$sub=['id'=>$sid0,'task_id'=>$id,'telegram_id'=>$u['telegram_id'],'manager_id'=>$mid,'profile_link'=>$profile,'proof_file'=>$upload['name'],'proof_sha'=>$upload['sha'],'status'=>'pending','reason'=>'','fraud_score'=>fraud($u['telegram_id']),'ts'=>n(),'created_at'=>iso()];setr('submissions',$sid0,$sub);dpatch('claims/'.$ck,['submission_id'=>$sid0,'status'=>'pending']);if($mid!=='')manager_notify($mid,'New Proof','নতুন proof review এসেছে');out(['ok'=>true,'status'=>'pending']);}$r=complete_task($id,$u['telegram_id']);out($r,$r['ok']?200:400);}
    if($a==='spin'){ $u=require_user();$s=spin_state($u['telegram_id']);if(!$s['ready'])out(['ok'=>false,'error'=>'spin_cooldown','state'=>$s],400);$slots=dget('settings/spin_slots',[]);$idx=random_int(0,min(6,count($slots))-1);$slot=$slots[$idx];$uu=getr('users',$u['telegram_id']);$uu['spin_last_ts']=n();setr('users',$u['telegram_id'],$uu);dset('spins/'.$u['telegram_id'].'/'.uuid(),['index'=>$idx,'slot'=>$slot,'ts'=>n()]);$r=money($slot['reward']??0);if($r>0){add_balance($u['telegram_id'],$r,'spin_reward',['index'=>$idx]);add_xp($u['telegram_id'],10);}out(['ok'=>true,'index'=>$idx,'slot'=>$slot,'state'=>spin_state($u['telegram_id'])]);}
    if($a==='streak'){ $u=require_user();$s=streak_state($u['telegram_id']);if($s['claimed'])out(['ok'=>false,'error'=>'already_claimed'],400);$uu=getr('users',$u['telegram_id']);$rw=round(min(2,.05*$s['days']),4);$uu['streak_days']=$s['days'];$uu['streak_last_date']=gmdate('Y-m-d');setr('users',$u['telegram_id'],$uu);add_balance($u['telegram_id'],$rw,'daily_streak',['days'=>$s['days']]);add_xp($u['telegram_id'],5);out(['ok'=>true,'reward'=>$rw,'days'=>$s['days']]);}
