    if($a==='withdraw'){ $u=require_user();$d=input();$amount=money($d['amount']??0);$min=money(dget('settings/min_withdraw',MIN_WITHDRAW));$method=text((string)($d['method']??''),30);$acct=text((string)($d['account']??''),200);if($amount<$min)out(['ok'=>false,'error'=>'minimum_withdraw_not_met','minimum'=>$min],400);if($amount>money($u['balance']??0))out(['ok'=>false,'error'=>'insufficient_balance'],400);if(!in_array($method,['binance','bkash','nagad','rocket'],true)||$acct==='')out(['ok'=>false,'error'=>'invalid_payout_details'],400);$mid=choose_manager();if($mid==='')out(['ok'=>false,'error'=>'no_manager_available'],503);$id=uuid();add_balance($u['telegram_id'],-$amount,'withdrawal_hold',['id'=>$id]);$w=['id'=>$id,'telegram_id'=>$u['telegram_id'],'manager_id'=>$mid,'amount'=>$amount,'method'=>$method,'account'=>$acct,'status'=>'pending','reason'=>'','fraud_score'=>fraud($u['telegram_id']),'ts'=>n(),'created_at'=>iso()];setr('withdrawals',$id,$w);manager_notify($mid,'New Withdrawal','নতুন withdrawal এসেছে');out(['ok'=>true,'withdrawal'=>$w]);}
    if($a==='profile'){ $u=require_user();$logs=cget('balance_logs/'.$u['telegram_id']);usort($logs,fn($a,$b)=>(int)($b['ts']??0)<=>(int)($a['ts']??0));out(['ok'=>true,'user'=>$u,'level'=>progress((int)$u['xp']),'logs'=>array_slice($logs,0,100),'referral_link'=>'https://t.me/'.TELEGRAM_USERNAME.'?start=ref_'.$u['telegram_id']]);}
    if($a==='public_stats'){out(['ok'=>true,'users'=>count(cget('users')),'tasks'=>count(cget('tasks')),'completed'=>array_sum(array_map(fn($x)=>(int)($x['tasks_completed']??0),cget('users')))]);}
    if($a==='admin_login'){ $d=input();$pw=(string)($d['password']??'');if(ADMIN_PASSWORD===''||!hash_equals(ADMIN_PASSWORD,$pw)){usleep(250000);out(['ok'=>false,'error'=>'invalid_credentials'],401);}$_SESSION['admin']=true;$_SESSION['admin_at']=n();session_regenerate_id(true);audit('admin_login');out(['ok'=>true]);}
    if($a==='admin_logout'){unset($_SESSION['admin'],$_SESSION['admin_at']);out(['ok'=>true]);}
    if($a==='manager_login'){ $d=input();$id=text((string)($d['manager_id']??''),100);$m=getr('managers',$id);if(!$m||empty($m['active'])||empty($m['password_hash'])||!password_verify((string)($d['password']??''),(string)$m['password_hash']))out(['ok'=>false,'error'=>'invalid_credentials'],401);$_SESSION['manager_id']=$id;$_SESSION['manager_at']=n();session_regenerate_id(true);out(['ok'=>true]);}
    if($a==='admin_bootstrap'){require_admin();out(['ok'=>true,'stats'=>['users'=>count(cget('users')),'tasks'=>count(cget('tasks')),'proofs'=>count(array_filter(cget('submissions'),fn($x)=>($x['status']??'')==='pending')),'withdrawals'=>count(array_filter(cget('withdrawals'),fn($x)=>($x['status']??'')==='pending')),'managers'=>count(cget('managers'))],'users'=>cget('users'),'tasks'=>cget('tasks'),'submissions'=>cget('submissions'),'withdrawals'=>cget('withdrawals'),'managers'=>cget('managers'),'campaigns'=>cget('campaigns'),'activity'=>array_slice(array_reverse(cget('activity')),0,300),'settings'=>dget('settings',[]),'meta'=>dget('meta',[])]);}
    if($a==='manager_bootstrap'){require_mgr();$mid=admin_ok()?'':(string)$_SESSION['manager_id'];$f=function($x)use($mid){return $mid===''||($x['manager_id']??'')===$mid;};out(['ok'=>true,'manager'=>$mid===''?['id'=>'admin','name'=>'Administrator']:getr('managers',$mid),'submissions'=>array_filter(cget('submissions'),$f),'withdrawals'=>array_filter(cget('withdrawals'),$f),'tasks'=>array_filter(cget('tasks'),$f),'open'=>$mid===''?0:manager_count($mid)]);}
    if($a==='task_save'){require_admin();$d=input();$id=text((string)($d['id']??''),100);$id=$id!==''?$id:uuid();$old=getr('tasks',$id);$t=['id'=>$id,'title'=>text((string)($d['title']??''),200),'description'=>text((string)($d['description']??''),1000),'category'=>text((string)($d['category']??'website'),40),'link'=>url((string)($d['link']??'')),'reward'=>money($d['reward']??0),'xp'=>max(0,min(10000,(int)($d['xp']??20))),'max_limit'=>max(0,min(MAX_TASK_LIMIT,(int)($d['max_limit']??0))),'completed_count'=>(int)($old['completed_count']??0),'require_screenshot'=>!empty($d['require_screenshot']),'require_profile_link'=>!empty($d['require_profile_link']),'require_review'=>!empty($d['require_review']),'manager_id'=>text((string)($d['manager_id']??''),100),'publish_at_ts'=>(int)($d['publish_at_ts']??0),'expires_at_ts'=>(int)($d['expires_at_ts']??0),'priority'=>max(0,min(9999,(int)($d['priority']??0))),'disabled'=>!empty($d['disabled']),'icon'=>url((string)($d['icon']??'')),'created_at'=>(string)($old['created_at']??iso()),'updated_at'=>iso()];if($t['title']===''||$t['link']==='')out(['ok'=>false,'error'=>'title_and_link_required'],400);setr('tasks',$id,$t);audit('task_save',$id);out(['ok'=>true,'task'=>$t]);}
    if($a==='task_delete'){require_admin();$d=input();$id=text((string)($d['id']??''),100);delr('tasks',$id);audit('task_delete',$id);out(['ok'=>true]);}
    if($a==='submission_review'){require_mgr();$d=input();$id=text((string)($d['id']??''),100);$st=text((string)($d['status']??''),20);$reason=text((string)($d['reason']??''),500);$s=getr('submissions',$id);if(!$s||(!admin_ok()&&($s['manager_id']??'')!==(string)$_SESSION['manager_id']))out(['ok'=>false,'error'=>'not_your_queue'],403);if(($s['status']??'')!=='pending')out(['ok'=>false,'error'=>'already_reviewed'],400);$s['status']=$st;$s['reason']=$reason;$s['reviewed_at']=iso();setr('submissions',$id,$s);if($st==='approved'){$r=complete_task((string)$s['task_id'],(string)$s['telegram_id'],$id);if(!$r['ok'])out(['ok'=>false,'error'=>'completion_failed'],400);}else notify((string)$s['telegram_id'],'Task Rejected',$reason!==''?$reason:'Proof rejected','task');audit('submission_review',$id,['status'=>$st]);out(['ok'=>true]);}
    if($a==='withdraw_review'){require_mgr();$d=input();$id=text((string)($d['id']??''),100);$st=text((string)($d['status']??''),20);$reason=text((string)($d['reason']??''),500);$w=getr('withdrawals',$id);if(!$w||(!admin_ok()&&($w['manager_id']??'')!==(string)$_SESSION['manager_id']))out(['ok'=>false,'error'=>'not_your_queue'],403);if(($w['status']??'')!=='pending')out(['ok'=>false,'error'=>'already_reviewed'],400);$w['status']=$st;$w['reason']=$reason;$w['reviewed_at']=iso();setr('withdrawals',$id,$w);if($st==='rejected'){add_balance((string)$w['telegram_id'],money($w['amount']??0),'withdrawal_reversal',['id'=>$id]);notify((string)$w['telegram_id'],'Withdrawal Rejected',$reason!==''?$reason:'Rejected','withdrawal');}else{valid_ref_on_withdraw((string)$w['telegram_id']);$u=getr('users',(string)$w['telegram_id']);if($u){$u['withdrawals_total']=money($u['withdrawals_total']??0)+money($w['amount']??0);setr('users',(string)$w['telegram_id'],$u);}notify((string)$w['telegram_id'],'Withdrawal Approved','আপনার withdrawal approved হয়েছে','withdrawal');}audit('withdraw_review',$id,['status'=>$st]);out(['ok'=>true]);}
    if($a==='reassign'){require_admin();$d=input();$type=text((string)($d['type']??''),20);$id=text((string)($d['id']??''),100);$mid=text((string)($d['manager_id']??''),100);$c=$type==='task'?'tasks':($type==='submission'?'submissions':'withdrawals');$x=getr($c,$id);if(!$x)out(['ok'=>false,'error'=>'not_found'],404);$x['manager_id']=$mid;setr($c,$id,$x);audit('reassign',$id,['type'=>$type,'manager'=>$mid]);out(['ok'=>true]);}
    if($a==='manager_save'){require_admin();$d=input();$id=text((string)($d['id']??''),100);$id=$id!==''?$id:uuid();$old=getr('managers',$id);$m=['id'=>$id,'name'=>text((string)($d['name']??''),100),'username'=>text((string)($d['username']??''),80),'active'=>!empty($d['active']),'max_open'=>max(1,min(10000,(int)($d['max_open']??MANAGER_MAX_OPEN))),'created_at'=>(string)($old['created_at']??iso()),'updated_at'=>iso(),'password_hash'=>(string)($old['password_hash']??'')];if(!empty($d['password']))$m['password_hash']=password_hash((string)$d['password'],PASSWORD_DEFAULT);if($m['password_hash']==='')$m['password_hash']=password_hash(bin2hex(random_bytes(10)),PASSWORD_DEFAULT);setr('managers',$id,$m);audit('manager_save',$id);out(['ok'=>true]);}
    if($a==='manager_delete'){require_admin();$d=input();$id=text((string)($d['id']??''),100);delr('managers',$id);audit('manager_delete',$id);out(['ok'=>true]);}
    if($a==='settings_save'){require_admin();$d=input();$s=dget('settings',[]);if(isset($d['min_withdraw']))$s['min_withdraw']=money($d['min_withdraw']);if(isset($d['daily_ad_limit']))$s['daily_ad_limit']=max(0,min(100000,(int)$d['daily_ad_limit']));if(isset($d['manager_max_open']))$s['manager_max_open']=max(1,min(100000,(int)$d['manager_max_open']));if(isset($d['required_chats'])&&is_array($d['required_chats']))$s['required_chats']=array_values(array_filter(array_map(fn($v)=>text((string)$v,100),$d['required_chats'])));if(isset($d['spin_slots'])&&is_array($d['spin_slots']))$s['spin_slots']=array_slice($d['spin_slots'],0,6);if(isset($d['refs'])&&is_array($d['refs']))$s['refs']=array_slice($d['refs'],0,50);dset('settings',$s);audit('settings_save');out(['ok'=>true]);}
    if($a==='user_update'){require_admin();$d=input();$id=text((string)($d['telegram_id']??''),100);$u=getr('users',$id);if(!$u)out(['ok'=>false,'error'=>'not_found'],404);if(isset($d['balance_delta'])&&(float)$d['balance_delta']!==0)add_balance($id,(float)$d['balance_delta'],'admin_adjustment');if(isset($d['xp']))$u['xp']=max(0,(int)$d['xp']);if(isset($d['blocked']))$u['blocked']=!empty($d['blocked']);if(isset($d['suspended']))$u['suspended']=!empty($d['suspended']);setr('users',$id,$u);audit('user_update',$id);out(['ok'=>true]);}
    if($a==='campaign_save'){require_admin();$d=input();$id=text((string)($d['id']??''),100);$id=$id!==''?$id:uuid();setr('campaigns',$id,['id'=>$id,'title'=>text((string)($d['title']??''),200),'reward'=>money($d['reward']??0),'active'=>!empty($d['active']),'target_level'=>max(0,(int)($d['target_level']??0)),'created_at'=>iso(),'updated_at'=>iso()]);out(['ok'=>true]);}
    if($a==='maintenance'){require_admin();$d=input();dset('meta/maintenance',!empty($d['enabled']));audit('maintenance');out(['ok'=>true]);}
    if($a==='backup'){require_admin();if(!is_dir(BACKUP_DIR))@mkdir(BACKUP_DIR,0755,true);$db=furls()?['users'=>cget('users'),'tasks'=>cget('tasks'),'claims'=>cget('claims'),'submissions'=>cget('submissions'),'withdrawals'=>cget('withdrawals'),'managers'=>cget('managers'),'referrals'=>cget('referrals'),'ref_rewards'=>cget('ref_rewards'),'spins'=>cget('spins'),'streaks'=>cget('streaks'),'ads'=>cget('ads'),'notifications'=>cget('notifications'),'activity'=>cget('activity'),'campaigns'=>cget('campaigns'),'settings'=>dget('settings',[]),'meta'=>dget('meta',[])]:local_db();$f=BACKUP_DIR.'/backup-'.gmdate('Ymd-His').'.json';writej($f,$db);audit('backup',$f);out(['ok'=>true,'file'=>basename($f)]);}

    if($a==='binding_verify'){require_user();$d=input();$tid=text((string)($d['task_id']??''),100);$task=getr('tasks',$tid);if(!$task)out(['ok'=>false,'error'=>'task_not_found'],404);$uid=uid();$r=binding_verify($uid,$task,$d);if(!$r['ok'])out($r,422);$award=binding_claim($tid,$uid,money($task['reward']??0),(int)($task['xp']??10));if(!$award['ok'])out($award,409);$task['completed_count']=(int)($task['completed_count']??0)+1;if((int)($task['max_limit']??0)>0&&$task['completed_count']>=(int)$task['max_limit'])$task['disabled']=true;setr('tasks',$tid,$task);out(['ok'=>true,'award'=>$award]);}
    if($a==='bindings'){require_user();$x=dget('bindings/'.uid(),[]);out(['ok'=>true,'bindings'=>is_array($x)?$x:[]]);}
    if($a==='export_users'){require_mgr();header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="users.csv"');$o=fopen('php://output','w');fputcsv($o,['telegram_id','name','username','balance','xp','tasks_completed','valid_referral_count','fraud_score']);foreach(cget('users') as $id=>$u)fputcsv($o,[$id,$u['name']??'',$u['username']??'',$u['balance']??0,$u['xp']??0,$u['tasks_completed']??0,$u['valid_referral_count']??0,$u['fraud_score']??0]);fclose($o);exit;}
    if($a==='export_withdrawals'){require_mgr();header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="withdrawals.csv"');$o=fopen('php://output','w');fputcsv($o,['id','telegram_id','manager_id','amount','method','account','status','fraud_score','created_at']);foreach(cget('withdrawals') as $id=>$w)fputcsv($o,[$id,$w['telegram_id']??'',$w['manager_id']??'',$w['amount']??0,$w['method']??'',$w['account']??'',$w['status']??'',$w['fraud_score']??0,$w['created_at']??'']);fclose($o);exit;}
    if($a==='webhook'){
        $secret=(string)($_SERVER['HTTP_X_TELEGRAM_BOT_API_SECRET_TOKEN']??'');
        if(WEBHOOK_SECRET!==''&&!hash_equals(WEBHOOK_SECRET,$secret)) out(['ok'=>false,'error'=>'webhook_secret_invalid'],403);
        $u=dec((string)file_get_contents('php://input'),[]);
        if(!is_array($u)) out(['ok'=>true]);
        if(!empty($u['callback_query'])){
            $cb=$u['callback_query'];
            $cid=(string)($cb['message']['chat']['id']??'');
            $cbid=(string)($cb['id']??'');
            if($cbid!=='') tg('answerCallbackQuery',['callback_query_id'=>$cbid]);
            if($cid!==''){
                $keyboard=['inline_keyboard'=>[[['text'=>'🇧🇩 বাংলা','web_app'=>['url'=>app_url('?lang=bn&start=')]]],[['text'=>'🇬🇧 English','web_app'=>['url'=>app_url('?lang=en&start=')]]]]];
                tg('sendMessage',['chat_id'=>$cid,'text'=>'ভাষা নির্বাচন করুন / Choose your language','reply_markup'=>json_encode($keyboard,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);
            }
        }
        if(!empty($u['message']['text'])&&preg_match('/^\/start(?:@\w+)?(?:\s+(.+))?$/u',trim((string)$u['message']['text']),$m)){
            $start=$m[1]??'';$cid=(string)($u['message']['chat']['id']??'');$nm=(string)($u['message']['from']['first_name']??'বন্ধু');
            $bn=app_url('?lang=bn&start='.rawurlencode($start));
            $en=app_url('?lang=en&start='.rawurlencode($start));
            $keyboard=['inline_keyboard'=>[[['text'=>'🇧🇩 বাংলা','web_app'=>['url'=>$bn]]],[['text'=>'🇬🇧 English','web_app'=>['url'=>$en]]]]];
            if($cid!=='') tg('sendMessage',['chat_id'=>$cid,'text'=>'স্বাগতম '.$nm.'! FoxiGrow-এ আয় ও টাস্ক শুরু করুন। 🚀\n\nভাষা নির্বাচন করুন / Choose your language','reply_markup'=>json_encode($keyboard,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);
        }
        out(['ok'=>true,'update_id'=>$u['update_id']??0]);
    }
    if($a==='proof_purge'){ $key=(string)($_GET['key']??''); if(ADMIN_SHARED_KEY===''||!hash_equals(ADMIN_SHARED_KEY,$key))out(['ok'=>false,'error'=>'forbidden'],403); $file=basename((string)($_GET['file']??'')); $hash=text((string)($_GET['hash']??''),100); $path=UPLOAD_DIR.'/'.$file; if(is_file($path))@unlink($path); if($hash!=='')dset('proof_hashes/'.$hash,null); out(['ok'=>true]);}
    out(['ok'=>false,'error'=>'unknown_action'],404);
}

