function static_action():void{
    $a=action();
    if($a==='pwa_manifest'){
        header('Content-Type: application/manifest+json');
        echo json_encode(['name'=>APP_NAME,'short_name'=>APP_NAME,'start_url'=>app_url(),'display'=>'standalone','background_color'=>'#08080d','theme_color'=>'#08080d','icons'=>[]],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
        exit;
    }
    if($a==='service_worker'){
        header('Content-Type: application/javascript');
        echo 'self.addEventListener("install",e=>self.skipWaiting());self.addEventListener("activate",e=>self.clients.claim());self.addEventListener("fetch",e=>{});';
        exit;
    }
    if(isset($_GET['proof_key'])){
        $key=(string)$_GET['proof_key'];
        if(ADMIN_SHARED_KEY===''||!hash_equals(ADMIN_SHARED_KEY,$key)){http_response_code(403);exit;}
        $f=basename((string)($_GET['proof_file']??''));
        $p=UPLOAD_DIR.'/'.$f;
        if(!is_file($p)){http_response_code(404);exit;}
        $m=(new finfo(FILEINFO_MIME_TYPE))->file($p)?:'application/octet-stream';
        header('Content-Type:'.$m);
        header('Content-Disposition: inline; filename="'.$f.'"');
        header('X-Content-Type-Options:nosniff');
        readfile($p);
        exit;
    }
    if(isset($_GET['proof'])){
        require_mgr();
        $f=basename((string)$_GET['proof']);
        $p=UPLOAD_DIR.'/'.$f;
        if(!is_file($p)){http_response_code(404);exit;}
        $m=(new finfo(FILEINFO_MIME_TYPE))->file($p)?:'application/octet-stream';
        header('Content-Type:'.$m);
        header('Content-Disposition: inline; filename="'.$f.'"');
        header('X-Content-Type-Options:nosniff');
        readfile($p);
        exit;
    }
}
$actionName=action();
if(in_array($actionName,['pwa_manifest','service_worker'],true)||isset($_GET['proof'])||isset($_GET['proof_key'])) static_action();
if($actionName!=='') api();
if(isset($_GET['manager'])){
    echo head_html(APP_NAME.' Manager','manager').'<script>'.js_common().adminScript().'</script><script>managerPage()</script></body></html>';
    exit;
}
if(trim(parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH)??'','/')===ADMIN_PATH||isset($_GET['admin'])){
    echo head_html(APP_NAME.' Admin','admin').'<script>'.js_common().adminScript().'</script><script>loadAdmin()</script></body></html>';
    exit;
}
$mon='';
if(MONETAG_SCRIPT_URL!=='') $mon='<script src="'.h(MONETAG_SCRIPT_URL).'" data-zone="'.h(MONETAG_ZONE_ID).'" data-sdk="show_'.h(MONETAG_ZONE_ID).'" defer></script>';
echo head_html(APP_NAME).$mon.'<script>'.js_common().userScript().'</script><div id="modal" class="modal"><div id="sheet" class="sheet"></div></div><script>startUser()</script></body></html>';
?>
